sys_script_include.script:
var CheckParkingSlot = Class.create();
CheckParkingSlot.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    checkSlot: function() {

        var slotId = this.getParameter('sysparm_slot_id');

        if (!slotId) {
            return 'invalid';
        }

        var slot = new GlideRecord('x_2137028_validp_0_parking_slot');

        if (slot.get(slotId)) {
            return slot.getValue('u_status');
        }

        return 'not_found';
    },

    type: 'CheckParkingSlot'
});
